import{G as e,W as t,n,rt as r}from"./chunks/framework.CHX_0itn.js";var i=JSON.parse(`{"title":"眼视光学 · 学科概览","description":"","frontmatter":{"next":false},"headers":[],"relativePath":"welcome.md","filePath":"welcome.md"}`),a={name:`welcome.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="眼视光学-·-学科概览" tabindex="-1">眼视光学 · 学科概览 <a class="header-anchor" href="#眼视光学-·-学科概览" aria-label="Permalink to “眼视光学 · 学科概览”">​</a></h1><blockquote><p><strong>以光为器，以眼为本，以视觉为归。</strong></p></blockquote><h2 id="什么是眼视光学" tabindex="-1">什么是眼视光学 <a class="header-anchor" href="#什么是眼视光学" aria-label="Permalink to “什么是眼视光学”">​</a></h2><p><strong>眼视光学（Optometry）</strong> 是一门<strong>现代光学技术与现代眼科学相结合</strong>、以<strong>保护人眼视觉健康</strong>为宗旨，运用光学理论与技术<strong>解决视觉障碍</strong>的交叉学科。</p><p>它融合现代医学、生理光学、应用光学、生物医学工程等知识，融<strong>医疗、预防、保健、康复</strong>为一体。</p><h2 id="发展脉络-从一块镜片到一门学科" tabindex="-1">发展脉络：从一块镜片到一门学科 <a class="header-anchor" href="#发展脉络-从一块镜片到一门学科" aria-label="Permalink to “发展脉络：从一块镜片到一门学科”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>里程碑</th></tr></thead><tbody><tr><td>起源（13 世纪）</td><td>眼镜在欧洲出现，人类第一次用光学手段辅助视力</td></tr><tr><td>成型（19 世纪）</td><td>检影验光等技术确立，「视光学」概念提出，验光从眼镜手艺走向独立职业</td></tr><tr><td>成科（20 世纪）</td><td>视光学教育与国际职业体系建立，角膜接触镜、视觉训练、低视力康复相继拓展</td></tr><tr><td>融合（当代）</td><td>与眼科学深度结合，在中国形成本土化的眼视光学学科体系</td></tr></tbody></table><h2 id="今天的眼视光学在做什么" tabindex="-1">今天的眼视光学在做什么 <a class="header-anchor" href="#今天的眼视光学在做什么" aria-label="Permalink to “今天的眼视光学在做什么”">​</a></h2><ul><li><strong>从「配镜」到「视觉健康管理」</strong>：服务的不再只是度数，而是全生命周期的视觉质量</li><li><strong>从「治疗」到「预防」</strong>：儿童青少年近视防控上升为国家战略，保健关口前移</li><li><strong>技术持续升级</strong>：角膜塑形镜、屈光手术、双眼视功能训练、智能验光设备不断演进</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};